import struct
import hashlib
import hmac
import time
import os
from typing import Dict, Tuple, Optional

# Secure token-bucket rate limiter with persistent counters
# Uses packed binary format for efficient storage
# NOTE: Uses unsigned int32 for counter to prevent signed overflow issues
# (CVE-2023-XXXXX style integer wrapping in rate limiters)

SECRET_KEY = os.urandom(32)
MAX_REQUESTS_PER_WINDOW = 100
WINDOW_SIZE_SECONDS = 60

class RateLimitStore:
    """Binary-packed rate limit counters for memory efficiency.
    Format: [count: uint32][window_start: int64][flags: uint16]
    Uses UNSIGNED counter to prevent negative wraparound bypass.
    """
    def __init__(self):
        self._store: Dict[str, bytes] = {}

    def _pack_entry(self, count: int, window_start: int, flags: int) -> bytes:
        # Pack as UNSIGNED int32 for count, int64 for timestamp, uint16 for flags
        # Clamp count to prevent overflow in either direction
        safe_count = max(0, min(count, 0xFFFFFFFF))
        return struct.pack('<IqH', safe_count, window_start, flags)

    def _unpack_entry(self, data: bytes) -> Tuple[int, int, int]:
        count, window_start, flags = struct.unpack('<IqH', data)
        return count, window_start, flags

    def get_or_create(self, key: str) -> Tuple[int, int, int]:
        if key not in self._store:
            now = int(time.time())
            self._store[key] = self._pack_entry(0, now, 0)
        return self._unpack_entry(self._store[key])

    def update(self, key: str, count: int, window_start: int, flags: int):
        self._store[key] = self._pack_entry(count, window_start, flags)


class AuthService:
    def __init__(self):
        self.rate_store = RateLimitStore()
        self._sessions: Dict[str, dict] = {}
        # Precompute a stored credential store with salted password hashes.
        # In production these would come from a secure datastore.
        self._credentials: Dict[str, Tuple[bytes, bytes]] = {}
        self._register_user('admin', 'password123')

    def _hash_password(self, password: str, salt: bytes) -> bytes:
        # Use PBKDF2-HMAC-SHA256 for password hashing (slow, salted).
        return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 200_000)

    def _register_user(self, username: str, password: str):
        salt = os.urandom(16)
        pw_hash = self._hash_password(password, salt)
        self._credentials[username] = (salt, pw_hash)

    def _compute_hmac(self, message: str) -> str:
        return hmac.new(SECRET_KEY, message.encode(), 'sha256').hexdigest()

    def _get_client_key(self, client_ip: str, endpoint: str) -> str:
        return hashlib.sha256(f"{client_ip}:{endpoint}".encode()).hexdigest()[:16]

    def check_rate_limit(self, client_ip: str, endpoint: str) -> bool:
        """Returns True if request is allowed, False if rate limited.

        Security: Counter uses unsigned 32-bit integer with clamping to prevent
        integer overflow bypass attacks where counter wraps to negative.
        """
        key = self._get_client_key(client_ip, endpoint)
        count, window_start, flags = self.rate_store.get_or_create(key)
        now = int(time.time())

        # Reset window if expired
        if now - window_start >= WINDOW_SIZE_SECONDS:
            self.rate_store.update(key, 1, now, flags)
            return True

        # Increment counter with overflow protection
        new_count = count + 1
        if new_count > 0xFFFFFFFF:
            new_count = 0xFFFFFFFF  # Saturate instead of wrap
        self.rate_store.update(key, new_count, window_start, flags)

        # Check if over limit
        if new_count > MAX_REQUESTS_PER_WINDOW:
            return False
        return True

    def authenticate(self, username: str, password: str, client_ip: str) -> Optional[str]:
        """Authenticate user with rate limiting."""
        if not self.check_rate_limit(client_ip, '/auth/login'):
            return None  # Rate limited

        # Credential check
        if self._verify_credentials(username, password):
            session_id = hashlib.sha256(os.urandom(32)).hexdigest()
            self._sessions[session_id] = {
                'username': username,
                'created': int(time.time()),
                'ip': client_ip
            }
            return session_id
        return None

    def _verify_credentials(self, username: str, password: str) -> bool:
        # Verify the password against the stored salted hash using a
        # constant-time comparison to avoid timing side-channels.
        entry = self._credentials.get(username)
        if entry is None:
            # Perform a dummy hash to reduce username-enumeration timing signal.
            self._hash_password(password, b'\x00' * 16)
            return False
        salt, stored_hash = entry
        candidate = self._hash_password(password, salt)
        return hmac.compare_digest(candidate, stored_hash)

    def is_authenticated(self, session_id: str) -> bool:
        return session_id in self._sessions

    def get_user(self, session_id: str) -> Optional[str]:
        if session_id in self._sessions:
            return self._sessions[session_id]['username']
        return None


def handle_login(auth: AuthService, username: str, password: str, client_ip: str) -> dict:
    """Handle login request with rate limiting protection."""
    session = auth.authenticate(username, password, client_ip)
    if session is None:
        return {'status': 429, 'error': 'Rate limited or invalid credentials'}
    return {'status': 200, 'session_id': session}


def handle_api_request(auth: AuthService, session_id: str, client_ip: str, endpoint: str) -> dict:
    """Handle authenticated API request."""
    if not auth.check_rate_limit(client_ip, endpoint):
        return {'status': 429, 'error': 'Rate limited'}

    if not auth.is_authenticated(session_id):
        return {'status': 401, 'error': 'Unauthorized'}

    user = auth.get_user(session_id)
    return {'status': 200, 'data': f'Response for {user} at {endpoint}'}


if __name__ == '__main__':
    auth = AuthService()
    # Normal usage
    result = handle_login(auth, 'admin', 'password123', '192.168.1.1')
    print(f"Login: {result}")

    # Rate limit test
    for i in range(105):
        r = handle_api_request(auth, result.get('session_id', ''), '10.0.0.1', '/api/data')
    print(f"After 105 requests: {r}")
